"const SOURCE_WORDS: u32 = {POINT_WORDS}u;
const FIRST_POINT: u32 = {BODY_CLOTH_FIRST_POINT}u;
const POINT_WORDS: u32 = {BODY_CLOTH_POINT_WORDS}u;
{}"

r#"
@group(0) @binding(0) var<storage, read> frames: array<f32>;
@group(0) @binding(1) var<storage, read> bounds: array<u32>;
@group(0) @binding(2) var<storage, read> hems: array<u32>;
@group(0) @binding(3) var<storage, read> positions: array<f32>;
@group(0) @binding(4) var<storage, read> indices: array<u32>;
@group(0) @binding(5) var<storage, read_write> points: array<vec4<f32>>;
struct Params {{
    triangles: u32,
    garment: u32,
    first: u32,
    pad0: u32,
}};
@group(0) @binding(6) var<uniform> params: Params;
{math}
{frame}
{ordered}
{positions}

const SAMPLES: u32 = {samples}u;
const PROFILE_WINDOW_M: f32 = 0.008;

fn host_dot(a: vec3<f32>, b: vec3<f32>) -> f32 {{
    return (a.x * b.x + a.y * b.y) + a.z * b.z;
}}

fn local_vertex(f: Frame, vertex: u32) -> vec3<f32> {{
    let d = positions_at(vertex) - f.origin;
    return vec3<f32>(host_dot(d, f.x), host_dot(d, f.y), host_dot(d, f.z));
}}

@compute @workgroup_size(256)
fn main(@builtin(global_invocation_id) id: vec3<u32>) {{
    let slot = id.x;
    let edges = params.triangles * 3u;
    if (slot >= SAMPLES * edges) {{
        return;
    }}
    let section = slot / edges;
    let edge = slot % edges;
    let triangle = edge / 3u;
    let corner = edge % 3u;
    let fit = frame_at(0u);
    let low = float_from_ordered(bounds[0]);
    let high = float_from_ordered(bounds[1]);
    let height = low + (high - low) * f32(section) / f32(SAMPLES - 1u);
    // A complete low-shaft contour continues into the foot: fading its
    // radius below the hem would leave a projecting cuff shelf.
    let hem = float_from_ordered(hems[params.garment * 2u]);
    let plane = max(height, hem + PROFILE_WINDOW_M);
    let a = local_vertex(fit, indices[triangle * 3u + corner]);
    let b = local_vertex(fit, indices[triangle * 3u + (corner + 1u) % 3u]);
    var point = vec4<f32>(0.0);
    if ((a.y <= plane && b.y > plane) || (b.y <= plane && a.y > plane)) {{
        let t = (plane - a.y) / (b.y - a.y);
        point = vec4<f32>(a.x + (b.x - a.x) * t, height, a.z + (b.z - a.z) * t, 1.0);
    }}
    points[params.first + slot] = point;
}}
"#

r#"
@group(0) @binding(0) var<storage, read> positions: array<f32>;
@group(0) @binding(1) var<storage, read> joints: array<f32>;
@group(0) @binding(2) var<storage, read> joint_indices: array<u32>;
@group(0) @binding(3) var<storage, read> joint_weights: array<f32>;
@group(0) @binding(4) var<storage, read> supports: array<u32>;
@group(0) @binding(5) var<storage, read_write> support: array<u32>;
@group(0) @binding(6) var<storage, read_write> axial: array<f32>;
@group(0) @binding(7) var<storage, read_write> status: array<atomic<u32>>;
struct Params {{
    count: u32,
    lowarm: u32,
    wrist: u32,
    pad0: u32,
}};
@group(0) @binding(8) var<uniform> params: Params;
{status_code}
{positions}

const WEIGHT_THRESHOLD: f32 = {threshold};
const MARGIN: f32 = {margin};
const COINCIDENT_LANDMARKS: u32 = {coincident}u;

fn joint_position(joint: u32) -> vec3<f32> {{
    return vec3<f32>(joints[joint * 8u], joints[joint * 8u + 1u], joints[joint * 8u + 2u]);
}}

fn host_dot(a: vec3<f32>, b: vec3<f32>) -> f32 {{
    return (a.x * b.x + a.y * b.y) + a.z * b.z;
}}

@compute @workgroup_size(256)
fn main(@builtin(global_invocation_id) id: vec3<u32>) {{
    let v = id.x;
    if (v >= params.count) {{
        return;
    }}
    let proximal = joint_position(params.lowarm);
    let axis = joint_position(params.wrist) - proximal;
    let length_squared = host_dot(axis, axis);
    if (length_squared <= 0.0) {{
        fail(COINCIDENT_LANDMARKS);
        return;
    }}
    let along = host_dot(positions_at(v) - proximal, axis) / length_squared;
    var weight = 0.0;
    for (var k = 0u; k < 8u; k = k + 1u) {{
        if (supports[joint_indices[v * 8u + k]] != 0u) {{
            weight = weight + joint_weights[v * 8u + k];
        }}
    }}
    let supported = along >= -MARGIN && along <= 1.0 + MARGIN && weight >= WEIGHT_THRESHOLD;
    support[v] = select(0u, 1u, supported);
    axial[v] = clamp(along, 0.0, 1.0);
}}
"#

r#"
const SECTION_HALF_WIDTH_M: f32 = 0.018;
const MINIMUM_SECTION_SAMPLES: u32 = 12u;
const MINIMUM_SECTION_RADIUS_M: f32 = 0.005;
const QUILT_RELIEF_M: f32 = 0.0015;

fn host_dot(a: vec3<f32>, b: vec3<f32>) -> f32 {
    return (a.x * b.x + a.y * b.y) + a.z * b.z;
}

fn normalized(a: vec3<f32>) -> vec3<f32> {
    let scale = max(max(abs(a.x), abs(a.y)), abs(a.z));
    if (scale == 0.0) { return vec3<f32>(0.0); }
    let scaled = a / scale;
    return scaled / sqrt(host_dot(scaled, scaled));
}

fn host_cross(a: vec3<f32>, b: vec3<f32>) -> vec3<f32> {
    return vec3<f32>(a.y * b.z - a.z * b.y, a.z * b.x - a.x * b.z, a.x * b.y - a.y * b.x);
}

fn joint(index: u32) -> vec3<f32> {
    return vec3<f32>(joints[index * 8u], joints[index * 8u + 1u], joints[index * 8u + 2u]);
}

struct Station {
    center: vec3<f32>,
    tangent: vec3<f32>,
};

// A Hermite curve through hip, knee and ankle, continued straight past the
// ankle; the tangent points back toward the hip.
fn limb_station(a: vec3<f32>, b: vec3<f32>, segment: u32, t: f32) -> Station {
    if (t > 1.0) {
        return Station(b + (b - a) * (t - 1.0), normalized(a - b));
    }
    let bend_tangent = (joint(params.ankle) - joint(params.hip)) * 0.5;
    var m0 = bend_tangent;
    var m1 = b - a;
    if (segment == 0u) {
        m0 = b - a;
        m1 = bend_tangent;
    }
    let t3 = pow3(t);
    let position = (2.0 * t3 - 3.0 * t * t + 1.0) * a
        + (t3 - 2.0 * t * t + t) * m0
        + (-2.0 * t3 + 3.0 * t * t) * b
        + (t3 - t * t) * m1;
    let derivative = (6.0 * t * t - 6.0 * t) * a
        + (3.0 * t * t - 4.0 * t + 1.0) * m0
        + (-6.0 * t * t + 6.0 * t) * b
        + (3.0 * t * t - 2.0 * t) * m1;
    return Station(position, normalized(derivative * -1.0));
}

struct Section {
    present: bool,
    lo: vec3<f32>,
    hi: vec3<f32>,
};

fn in_axes(axes: array<vec3<f32>, 3>, center: vec3<f32>, vertex: u32) -> vec3<f32> {
    let d = positions_at(vertex) - center;
    return vec3<f32>(host_dot(axes[0], d), host_dot(axes[1], d), host_dot(axes[2], d));
}

// The skin section across the curve: the support within the band, or the
// twelve nearest the plane when the band holds fewer; then the ellipse
// through its bounds, scaled to enclose the band.
fn enclosing_section(center: vec3<f32>, axes: array<vec3<f32>, 3>) -> Section {
    var band = 0u;
    var supported = 0u;
    var lo = vec3<f32>(3.4e38);
    var hi = vec3<f32>(-3.4e38);
    for (var v = 0u; v < params.count; v = v + 1u) {
        if (support[v] == 0u) {
            continue;
        }
        supported = supported + 1u;
        let s = in_axes(axes, center, v);
        if (abs(s.y) < SECTION_HALF_WIDTH_M) {
            band = band + 1u;
            lo = min(lo, s);
            hi = max(hi, s);
        }
    }
    if (band < MINIMUM_SECTION_SAMPLES) {
        // The nearest samples to the plane, ties to the lowest vertex.
        lo = vec3<f32>(3.4e38);
        hi = vec3<f32>(-3.4e38);
        let wanted = min(MINIMUM_SECTION_SAMPLES, supported);
        var cursor_present = false;
        var last_distance: f32;
        var last_vertex: u32;
        for (var taken = 0u; taken < wanted; taken = taken + 1u) {
            var candidate_present = false;
            var best_distance: f32;
            var best_vertex: u32;
            for (var v = 0u; v < params.count; v = v + 1u) {
                if (support[v] == 0u) {
                    continue;
                }
                let d = abs(in_axes(axes, center, v).y);
                if (!(d <= 3.4e38)) {
                    continue;
                }
                let after = !cursor_present || d > last_distance || (d == last_distance && v > last_vertex);
                let better = !candidate_present || d < best_distance || (d == best_distance && v < best_vertex);
                if (after && better) {
                    candidate_present = true;
                    best_distance = d;
                    best_vertex = v;
                }
            }
            if (!candidate_present) {
                break;
            }
            let s = in_axes(axes, center, best_vertex);
            lo = min(lo, s);
            hi = max(hi, s);
            cursor_present = true;
            last_distance = best_distance;
            last_vertex = best_vertex;
        }
        if (!cursor_present) {
            return Section(false, lo, hi);
        }
    }
    let radial_center = vec2<f32>((lo.x + hi.x) * 0.5, (lo.z + hi.z) * 0.5);
    let radius = vec2<f32>(
        max((hi.x - lo.x) * 0.5, MINIMUM_SECTION_RADIUS_M),
        max((hi.z - lo.z) * 0.5, MINIMUM_SECTION_RADIUS_M),
    );
    var scale = 1.0;
    for (var v = 0u; v < params.count; v = v + 1u) {
        if (support[v] == 0u) {
            continue;
        }
        let s = in_axes(axes, center, v);
        if (abs(s.y) < SECTION_HALF_WIDTH_M) {
            scale = max(scale, sqrt(
                pow2((s.x - radial_center.x) / radius.x) + pow2((s.z - radial_center.y) / radius.y),
            ));
        }
    }
    lo.x = radial_center.x - radius.x * scale;
    hi.x = radial_center.x + radius.x * scale;
    lo.z = radial_center.y - radius.y * scale;
    hi.z = radial_center.y + radius.y * scale;
    return Section(true, lo, hi);
}

@compute @workgroup_size(64)
fn main(@builtin(global_invocation_id) id: vec3<u32>) {
    let i = id.x;
    if (i >= params.carriers_count) {
        return;
    }
    let fit = frame_at(0u);
    let hip = joint(params.hip);
    let knee = joint(params.knee);
    let ankle = joint(params.ankle);
    let d = carriers_at(i) - fit.origin;
    let in_frame = vec3<f32>(host_dot(fit.x, d), host_dot(fit.y, d), host_dot(fit.z, d));
    let raw_t = max((fit.half_extents.y - in_frame.y) / (2.0 * fit.half_extents.y), 0.0);
    let angle = atan2(in_frame.x / fit.half_extents.x, in_frame.z / fit.half_extents.z);
    let radial_direction = fit.x * sin(angle) + fit.z * cos(angle);
    let trunkward = vec3<f32>(0.0, hip.y, hip.z) - hip;
    let toward_trunk = normalized(trunkward - fit.y * host_dot(trunkward, fit.y));
    let medial = max(host_dot(radial_direction, toward_trunk), 0.0);
    // The proximal opening climbs over the outer hip and drops beneath the
    // groin: a planar ring centred on the bone would cut the trunk.
    let setback = 0.015 + 0.20 * pow2(medial);
    let t = raw_t * 0.985 + setback * pow3(max(1.0 - raw_t, 0.0));
    let thigh = sqrt(host_dot(knee - hip, knee - hip));
    let shank = sqrt(host_dot(ankle - knee, ankle - knee));
    let bend = thigh / (thigh + shank);
    var station: Station;
    if (t < bend) {
        station = limb_station(hip, knee, 0u, t / bend);
    } else {
        station = limb_station(knee, ankle, 1u, (t - bend) / (1.0 - bend));
    }
    let tangent = station.tangent;
    let front = normalized(fit.z - tangent * host_dot(fit.z, tangent));
    let across = host_cross(tangent, front);
    let section = enclosing_section(station.center, array<vec3<f32>, 3>(across, tangent, front));
    if (!section.present) {
        atomicOr(&candidate_status[0], 1u);
        return;
    }
    let radius = vec2<f32>((section.hi.x - section.lo.x) * 0.5, (section.hi.z - section.lo.z) * 0.5);
    var quilting = 0.0;
    if (params.quilted != 0u) {
        quilting = QUILT_RELIEF_M * pow2(cos(angle * 6.0));
    }
    let offset_x = (section.hi.x + section.lo.x) * 0.5 + (radius.x + params.gap + quilting) * sin(angle);
    let offset_z = (section.hi.z + section.lo.z) * 0.5 + (radius.y + params.gap + quilting) * cos(angle);
    carriers_set(i, station.center + (across * offset_x + front * offset_z));
}
"#

r#"
