@compute @workgroup_size(1)
fn main() {
    let base = local(joint(params.neck));
    let chin = local(joint(params.jaw));
    let span = host_sub(local(joint(params.head)).y, base.y);
    if (!(span > 0.0)) {
        fail(INVALID);
