    let center = load(CENTER_DEPTH);
    let neck = section(i, load(SIDE_HEIGHT));
    if (neck.valid) {
        atomicMax(&work[NECK_WIDTH], ordered_from_float(max(abs(neck.a.x), abs(neck.b.x))));
        count_at(NECK_WIDTH);
