    // The checks of `PartFrame::validate`: orthonormal axes, positive extents,
    // finite words.
    var valid = true;
    for (var a = 0u; a < 3u; a = a + 1u) {
        for (var b = 0u; b < 3u; b = b + 1u) {
            let expected = select(0.0, 1.0, a == b);
            if (!(abs(host_dot(axis(a), axis(b)) - expected) < 0.001)) {
