const SUPPORT_MASK: u32 = 3u;

@compute @workgroup_size(1)
fn main() {
    let f = frame_at(0u);
    let center = host_point(f, vec3<f32>(0.0, f.half_extents.y, 0.0));
    let band = band_bounds(
        SUPPORT_MASK,
        center,
        f.x,
        f.y,
        f.z,
        SECTION_HALF_WIDTH_M,
        MINIMUM_SECTION_SAMPLES,
    );
