        fit[FIT_FAILED] = 1.0;
        return;
    }
    fit[12] = (band.hi.x - band.lo.x) * 0.5;
    fit[14] = (band.hi.z - band.lo.z) * 0.5;
    if (!(fit[12] > 0.0 && fit[14] > 0.0 && abs(fit[12]) <= INFINITY && abs(fit[14]) <= INFINITY)) {
        fit[FIT_FAILED] = 1.0;
