    let at = SECTIONS + row * SECTION_WORDS;
    fit[at] = y;
    for (var a = 0u; a < 3u; a = a + 1u) {
        fit[at + 1u + a] = band.lo[a];
        fit[at + 4u + a] = band.hi[a];
