    var hash = 2166136261u;
    for (var axis = 0u; axis < 3u; axis = axis + 1u) {{
        let q = quantize(positions[v * 3u + axis]);
        quantized[v * 3u + axis] = q;
        hash = (hash ^ bitcast<u32>(q)) * 16777619u;
    }}
    keys[v] = hash;
    values[v] = v;
}}
