r#"
var<private> ring_base: u32;

fn point(i: u32) -> vec3<f32> {
    return vec3<f32>(positions[i * 3u], positions[i * 3u + 1u], positions[i * 3u + 2u]);
}

fn body_of(vertex: u32) -> u32 {
    return surface[HEADER + vertex * 2u];
}

fn crossing_at(i: u32) -> u32 {
    return ring_base + i * POINT_WORDS;
}

fn crossing_position(i: u32) -> vec3<f32> {
    let at = crossing_at(i);
    return vec3<f32>(points[at + 5u], points[at + 6u], points[at + 7u]);
}

fn swap_crossings(i: u32, j: u32) {
    let a = crossing_at(i);
    let b = crossing_at(j);
    for (var k = 0u; k < POINT_WORDS; k = k + 1u) {
        let held = points[a + k];
        points[a + k] = points[b + k];
        points[b + k] = held;
    }
}

// Blend two crossings' samples into sample `slot`, merging repeated vertices
// and dropping negligible weights.
fn write_blend(slot: u32, a: u32, b: u32, factor: f32) {
    var keys: array<u32, 4>;
    var weights: array<f32, 4>;
    var n = 0u;
    for (var side = 0u; side < 2u; side = side + 1u) {
        var at = crossing_at(a);
        var scale = 1.0 - factor;
        if (side == 1u) {
            at = crossing_at(b);
            scale = factor;
        }
        let count = bitcast<u32>(points[at]);
        for (var e = 0u; e < count; e = e + 1u) {
            let key = bitcast<u32>(points[at + 1u + e]);
            let weight = points[at + 3u + e] * scale;
            if (!(weight > 1e-7)) {
                continue;
            }
            var found = false;
            for (var i = 0u; i < n; i = i + 1u) {
                if (keys[i] == key) {
                    weights[i] = weights[i] + weight;
                    found = true;
                }
            }
            if (!found) {
                keys[n] = key;
                weights[n] = weight;
                n = n + 1u;
            }
        }
    }
    for (var i = 1u; i < n; i = i + 1u) {
        var j = i;
        loop {
            if (j == 0u || keys[j - 1u] < keys[j]) {
                break;
            }
            let key = keys[j];
            keys[j] = keys[j - 1u];
            keys[j - 1u] = key;
            let weight = weights[j];
            weights[j] = weights[j - 1u];
            weights[j - 1u] = weight;
            j = j - 1u;
        }
    }
    var total = 0.0;
    for (var i = 0u; i < n; i = i + 1u) {
        total = total + weights[i];
    }
    let out = slot * SAMPLE_WORDS;
    samples[out] = n;
    for (var i = 0u; i < 4u; i = i + 1u) {
        var key = 0u;
        var weight = 0.0;
        if (i < n) {
            key = keys[i];
            weight = weights[i] / total;
        }
        samples[out + 1u + i] = key;
        samples[out + 5u + i] = bitcast<u32>(weight);
    }
}

@compute @workgroup_size(1)
fn main(@builtin(workgroup_id) group: vec3<u32>) {
    let ring = group.x;
    ring_base = ring * params.count * POINT_WORDS;
    load_flute();
    let factor = f32(ring) / f32(ALONG);
    let target_axial = clamp(design[5] + (design[6] - design[5]) * factor, 1e-4, 1.0 - 1e-4);
    let weld = axis[3];
    let faces = surface[1];
    var count = 0u;
    for (var f = 0u; f < faces; f = f + 1u) {
        for (var e = 0u; e < 3u; e = e + 1u) {
            let a = surface[params.faces_at + f * 3u + e];
            let b = surface[params.faces_at + f * 3u + (e + 1u) % 3u];
            let start = axial[body_of(a)];
            let span = axial[body_of(b)] - start;
            if (abs(span) <= 1e-7) {
                continue;
            }
            let t = (target_axial - start) / span;
            if (!(t >= -1e-6 && t <= 1.0 + 1e-6)) {
                continue;
            }
            let clamped = clamp(t, 0.0, 1.0);
            var keys = vec2<u32>(a, b);
            var shares = vec2<f32>(1.0 - clamped, clamped);
            if (b < a) {
                keys = keys.yx;
                shares = shares.yx;
            }
            var kept_keys: array<u32, 2>;
            var kept: array<f32, 2>;
            var n = 0u;
            for (var i = 0u; i < 2u; i = i + 1u) {
                if (shares[i] > 1e-7) {
                    kept_keys[n] = keys[i];
                    kept[n] = shares[i];
                    n = n + 1u;
                }
            }
            var total = 0.0;
            for (var i = 0u; i < n; i = i + 1u) {
                total = total + kept[i];
            }
            var position = vec3<f32>(0.0);
            for (var i = 0u; i < n; i = i + 1u) {
                kept[i] = kept[i] / total;
                position = position + point(body_of(kept_keys[i])) * kept[i];
            }
            var welded = false;
            for (var j = 0u; j < count; j = j + 1u) {
                let d = position - crossing_position(j);
                if (sqrt(host_dot(d, d)) <= weld) {
                    welded = true;
                    break;
                }
            }
            if (welded) {
                continue;
            }
            if (count >= params.count) {
                fail(STATUS_INVALID_SURFACE);
                return;
            }
            let at = crossing_at(count);
            points[at] = bitcast<f32>(n);
            for (var i = 0u; i < 2u; i = i + 1u) {
                var key = 0u;
                var weight = 0.0;
                if (i < n) {
                    key = kept_keys[i];
                    weight = kept[i];
                }
                points[at + 1u + i] = bitcast<f32>(key);
                points[at + 3u + i] = weight;
            }
            points[at + 5u] = position.x;
            points[at + 6u] = position.y;
            points[at + 7u] = position.z;
            count = count + 1u;
        }
    }
    if (count < 3u) {
        fail(EMPTY_CONTOUR);
        return;
    }
    var sum = vec3<f32>(0.0);
    for (var j = 0u; j < count; j = j + 1u) {
        sum = sum + crossing_position(j);
    }
    let center = sum * (1.0 / f32(count));
    let u = vec3<f32>(axis[4], axis[5], axis[6]);
    let v = vec3<f32>(axis[8], axis[9], axis[10]);
    for (var j = 0u; j < count; j = j + 1u) {
        let radial = crossing_position(j) - center;
        points[crossing_at(j) + 8u] = atan2(host_dot(radial, v), host_dot(radial, u));
    }
    // Stable insertion sort by angle: equal angles keep their weld order.
    for (var i = 1u; i < count; i = i + 1u) {
        var j = i;
        loop {
            if (j == 0u || !(points[crossing_at(j - 1u) + 8u] > points[crossing_at(j) + 8u])) {
                break;
            }
            swap_crossings(j - 1u, j);
            j = j - 1u;
        }
    }
    let last = count - 1u;
    for (var c = 0u; c < params.around; c = c + 1u) {
        var column = design[DESIGN_COLUMNS + c];
        if (fluted()) {
            column = flute_fan(column, 1.0 - factor);
        }
        let target_angle = -PI + TAU * column;
        var a = last;
        var b = 0u;
        var start_angle = points[crossing_at(last) + 8u];
        var end_angle = points[crossing_at(0u) + 8u] + TAU;
        var bracketed = false;
        for (var e = 0u; e < last; e = e + 1u) {
            let low = points[crossing_at(e) + 8u];
            let high = points[crossing_at(e + 1u) + 8u];
            if (target_angle >= low && target_angle <= high) {
                a = e;
                b = e + 1u;
                start_angle = low;
                end_angle = high;
                bracketed = true;
                break;
            }
        }
        if (!bracketed && target_angle < points[crossing_at(0u) + 8u]) {
            start_angle = points[crossing_at(last) + 8u] - TAU;
            end_angle = points[crossing_at(0u) + 8u];
        }
        write_blend(ring * params.around + c, a, b, (target_angle - start_angle) / (end_angle - start_angle));
    }
}
"#

r#"
{math}
const HEADER: u32 = {header}u;
const ALONG: u32 = {along}u;
const SAMPLE_WORDS: u32 = {sample_words}u;
const POINT_WORDS: u32 = {point_words}u;
const DESIGN_COLUMNS: u32 = {design_columns}u;
const EMPTY_CONTOUR: u32 = {empty_contour}u;

fn host_dot(a: vec3<f32>, b: vec3<f32>) -> f32 {{
    return (a.x * b.x + a.y * b.y) + a.z * b.z;
}}

fn host_cross(a: vec3<f32>, b: vec3<f32>) -> vec3<f32> {{
    return vec3<f32>(a.y * b.z - a.z * b.y, a.z * b.x - a.x * b.z, a.x * b.y - a.y * b.x);
}}

// The unit vector along `v`, in xyz; w is one when `v` was longer than `minimum`.
fn unit_above(v: vec3<f32>, minimum: f32) -> vec4<f32> {{
    let magnitude = sqrt(host_dot(v, v));
    if (magnitude > minimum) {{
        return vec4<f32>(v * (1.0 / magnitude), 1.0);
    }}
    return vec4<f32>(v, 0.0);
}}

fn pow6(x: f32) -> f32 {{
    let s = x * x;
    return s * (s * s);
}}
"#

r#"
struct Params {
    count: u32,
    around: u32,
    faces_at: u32,
    record_body_normals: u32,
};
"#

r#"
var<private> flute: array<f32, 8>;

fn load_flute() {
    for (var k = 0u; k < 8u; k = k + 1u) {
        flute[k] = design[8u + k];
    }
}

fn fluted() -> bool {
    return design[7] != 0.0;
}

// `BracerDesign::relief`: end flares, the centre ridge, and the flutes.
fn relief(u: f32, v: f32) -> f32 {
    let edge = design[2] * pow6(1.0 - v) + design[3] * pow6(v);
    let ridge = pow8(max(cos(TAU * (u - 0.5)), 0.0)) * pow2(sin(PI * v)) * design[4];
    var total = edge + ridge;
    if (fluted()) {
        total = total + flute_relief(u, 1.0 - v);
    }
    return total;
}
"#

r#"
@group(0) @binding(0) var<storage, read> positions: array<f32>;
@group(0) @binding(1) var<storage, read> surface: array<u32>;
@group(0) @binding(2) var<storage, read> axial: array<f32>;
@group(0) @binding(3) var<storage, read> joint_weights: array<f32>;
@group(0) @binding(4) var<storage, read_write> axis: array<f32>;
@group(0) @binding(5) var<storage, read_write> status: array<atomic<u32>>;
@group(0) @binding(6) var<uniform> params: Params;

fn point(i: u32) -> vec3<f32> {
    return vec3<f32>(positions[i * 3u], positions[i * 3u + 1u], positions[i * 3u + 2u]);
}

@compute @workgroup_size(1)
fn main() {
    let n = surface[0];
    if (n == 0u) {
        fail(STATUS_INVALID_SURFACE);
        return;
    }
    let infinity = MAX_FINITE;
    var axial_sum = 0.0;
    var position_sum = vec3<f32>(0.0);
    var lowest = vec3<f32>(infinity);
    var highest = vec3<f32>(-infinity);
    for (var s = 0u; s < n; s = s + 1u) {
        let body = surface[HEADER + s * 2u];
        let p = point(body);
        axial_sum = axial_sum + axial[body];
        position_sum = position_sum + p;
        lowest = min(lowest, p);
        highest = max(highest, p);
        var weight = 0.0;
        for (var k = 0u; k < 8u; k = k + 1u) {
            weight = weight + joint_weights[body * 8u + k];
        }
        if (abs(weight - 1.0) > 1e-4 || !is_finite(p.x) || !is_finite(p.y) || !is_finite(p.z)) {
            fail(STATUS_INVALID_SURFACE);
        }
    }
    let count = f32(n);
    let mean_axial = axial_sum / count;
    let mean_position = position_sum * (1.0 / count);
    var regression = vec3<f32>(0.0);
    for (var s = 0u; s < n; s = s + 1u) {
        let body = surface[HEADER + s * 2u];
        regression = regression + (point(body) - mean_position) * (axial[body] - mean_axial);
    }
    let direction = unit_above(regression, 1e-8);
    if (direction.w == 0.0) {
        fail(STATUS_DEGENERATE);
        return;
    }
    let d = direction.xyz;
    var reference = vec3<f32>(0.0, 1.0, 0.0);
    if (abs(d.x) < 0.8) {
        reference = vec3<f32>(1.0, 0.0, 0.0);
    }
    let u = unit_above(host_cross(d, reference), 1e-8);
    if (u.w == 0.0) {
        fail(STATUS_DEGENERATE);
        return;
    }
    let v = host_cross(d, u.xyz);
    let extent = highest - lowest;
    let weld = max(sqrt(host_dot(extent, extent)) * 1e-5, 1e-7);
    var words = array<f32, 12>(d.x, d.y, d.z, weld, u.x, u.y, u.z, 0.0, v.x, v.y, v.z, 0.0);
    for (var k = 0u; k < 12u; k = k + 1u) {
        axis[k] = words[k];
    }
}
