fn fanned(u: f32, axial: f32) -> f32 {
    if (params.fluted != 0u) {
        return flute_fan(u, axial);
    }
    return u;
}

fn height(u: f32, axial: f32) -> f32 {
    var relief = 0.0;
    if (params.fluted != 0u) {
        relief = flute_relief(u, axial);
    }
    return chart_offset(u, axial) + relief;
}

