    let u = coord.x / f32(AROUND);
    let angle = u * TAU;
    let padding = design[CLEARANCE] + design[WALL] + quilt(design[PADDED] != 0.0, u);
    return ShellVertex(
        vec3<f32>(
            (width * radius + padding) * sin(angle),
            height - 2.0 * height * design[LENGTH] * (1.0 - axial),
            (depth * radius + padding) * cos(angle),
