// Barycentric weights of the closest point on a triangle.
// After Ericson, "Real-Time Collision Detection", 5.1.5.
fn closest_weights(p: vec3<f32>, t: Triangle) -> vec3<f32> {{
    let ab = t.b - t.a;
    let ac = t.c - t.a;
    let ap = p - t.a;
    let d1 = dot(ab, ap);
    let d2 = dot(ac, ap);
    if (d1 <= 0.0 && d2 <= 0.0) {{
        return vec3<f32>(1.0, 0.0, 0.0);
    }}
    let bp = p - t.b;
    let d3 = dot(ab, bp);
    let d4 = dot(ac, bp);
    if (d3 >= 0.0 && d4 <= d3) {{
        return vec3<f32>(0.0, 1.0, 0.0);
    }}
    let vc = d1 * d4 - d3 * d2;
    if (vc <= 0.0 && d1 >= 0.0 && d3 <= 0.0) {{
        let v = d1 / (d1 - d3);
        return vec3<f32>(1.0 - v, v, 0.0);
    }}
    let cp = p - t.c;
    let d5 = dot(ab, cp);
    let d6 = dot(ac, cp);
    if (d6 >= 0.0 && d5 <= d6) {{
        return vec3<f32>(0.0, 0.0, 1.0);
    }}
    let vb = d5 * d2 - d1 * d6;
    if (vb <= 0.0 && d2 >= 0.0 && d6 <= 0.0) {{
        let w = d2 / (d2 - d6);
        return vec3<f32>(1.0 - w, 0.0, w);
    }}
    let va = d3 * d6 - d5 * d4;
    if (va <= 0.0 && (d4 - d3) >= 0.0 && (d5 - d6) >= 0.0) {{
        let w = (d4 - d3) / ((d4 - d3) + (d5 - d6));
        return vec3<f32>(0.0, 1.0 - w, w);
    }}
    // All three face-region numerators are nonnegative. Normalize them
    // directly: subtracting rounded v and w from one can create a negative
    // first weight at a valid triangle edge.
    return vec3<f32>(va, vb, vc) / (va + vb + vc);
}}

