    var best_weights = vec3<f32>(0.0);
    let tiles = (params.target_count + {TILE}u - 1u) / {TILE}u;
    for (var tile = 0u; tile < tiles; tile = tile + 1u) {{
        let slot = tile * {TILE}u + local_id.x;
        if (slot < params.target_count) {{
