    var origin = vec3<f32>(0.0);
    var direction = vec3<f32>(0.0);
    if (answering) {{
        origin = load_query(query);
        direction = vec3<f32>(
            directions[query * 3u],
            directions[query * 3u + 1u],
            directions[query * 3u + 2u],
