        nearest[query] = best;
        weights[query * 3u] = 1.0 - best_uv.x - best_uv.y;
        weights[query * 3u + 1u] = best_uv.x;
        weights[query * 3u + 2u] = best_uv.y;
        distances[query] = best_t;
